function toSpawnOptions(options) {
    return {
        cwd: options.cwd,
        env: options.env,
        stdin: options.stdin,
        streamStdin: options.streamStdin ?? true,
        captureStdio: true,
    };
}
export function spawnCodeProcess(vm, command, args, options = {}) {
    if (options.signal?.aborted) {
        throw abortReason(options.signal);
    }
    if (options.timeoutMs !== undefined &&
        (!Number.isFinite(options.timeoutMs) || options.timeoutMs < 0)) {
        throw new RangeError("timeoutMs must be a finite, non-negative number");
    }
    const { pid } = vm.spawn(command, args, toSpawnOptions(options));
    const stdoutDecoder = new TextDecoder();
    const stderrDecoder = new TextDecoder();
    let stdout = "";
    let stderr = "";
    let callbackError;
    let aborted = false;
    let finalized = false;
    let waitPromise;
    const unsubscribeOutput = vm.onProcessOutput(pid, (event) => {
        try {
            if (event.stream === "stdout") {
                const text = stdoutDecoder.decode(event.data, { stream: true });
                stdout += text;
                options.onStdout?.(text);
            }
            else {
                const text = stderrDecoder.decode(event.data, { stream: true });
                stderr += text;
                options.onStderr?.(text);
            }
        }
        catch (error) {
            callbackError ??= error;
            vm.killProcess(pid);
        }
    });
    const abort = () => {
        aborted = true;
        vm.killProcess(pid);
    };
    options.signal?.addEventListener("abort", abort, { once: true });
    const timeout = options.timeoutMs === undefined
        ? undefined
        : setTimeout(() => vm.killProcess(pid), options.timeoutMs);
    const finalize = async () => {
        if (finalized)
            return;
        finalized = true;
        unsubscribeOutput();
        options.signal?.removeEventListener("abort", abort);
        if (timeout !== undefined)
            clearTimeout(timeout);
        stdout += stdoutDecoder.decode();
        stderr += stderrDecoder.decode();
        await options.onComplete?.();
    };
    const wait = () => {
        waitPromise ??= (async () => {
            let exitCode;
            try {
                exitCode = await vm.waitProcess(pid);
            }
            catch (waitError) {
                try {
                    await finalize();
                }
                catch (cleanupError) {
                    console.error("[agentos] process cleanup also failed after waitProcess rejected:", cleanupError);
                }
                throw waitError;
            }
            await finalize();
            if (aborted && options.signal)
                throw abortReason(options.signal);
            if (callbackError !== undefined)
                throw callbackError;
            return {
                success: exitCode === 0,
                exitCode,
                stdout,
                stderr,
            };
        })();
        return waitPromise;
    };
    return {
        pid,
        writeStdin: (data) => vm.writeProcessStdin(pid, data),
        closeStdin: () => vm.closeProcessStdin(pid),
        kill: (signal) => {
            if (signal === "SIGKILL")
                vm.killProcess(pid);
            else
                vm.stopProcess(pid);
        },
        wait,
    };
}
function abortReason(signal) {
    return signal.reason ?? new DOMException("Execution aborted", "AbortError");
}
export async function executeArgv(vm, command, args, options = {}) {
    return spawnCodeProcess(vm, command, args, {
        ...options,
        streamStdin: false,
    }).wait();
}
